#pragma once
#include "kstationFlashStateTask.h"
namespace kstation {
enum class StartupChild {None,Pins,WaitStates,PanelReset,LcdInitialize,InterruptSetup,TimerSetup,BoundsCheck,BootProbe,KeyboardInitialize,SerialSetup,SerialEnable,EncoderInitialize,PanelQueues,AdcStart,DspBootstrap,DspGlobals,DelayTables,StartupBanner,LcdCharacters,Metadata,Scheduler1,Scheduler2,Scheduler3,Scheduler4,Scheduler5,ClearUi,ArpInitialize,MidiInitialize,ClockInitialize,ReadAdc,ApplyAdc,BackupGlobals,LoadGlobals,LoadProgram,UpdateDisplay,ReadTick};
class StartupColdTask final {
public:enum class Stage{Prefix,Runtime,Main,Complete};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return waiting_;}void resume(){waiting_=false;}unsigned nextClocks(const FlashCredits&c)const{return waiting_||complete()?0:stage_==Stage::Prefix?c.shortCall:stage_==Stage::Runtime?c.call:8;}unsigned advanceBefore(unsigned budget,const FlashCredits&c){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;if(stage_!=Stage::Main)waiting_=true;stage_=Stage(unsigned(stage_)+1);return cost;}
private:Stage stage_=Stage::Prefix;bool waiting_=false;};
class StartupPrefixTask final {
public:enum class Stage{Pins,WaitStates,PanelReset,RetainDelay,CountSettling,RetainInner,CountDelay,TickDelay,RepeatDelay,ReleaseInner,TickSettling,RepeatSettling,ReleaseDelay,LcdInitialize,InterruptSetup,TimerSetup,BoundsCheck,ClearMarker,PublishMarker,BootProbe,ReadMarker,Compare55,Select55,CompareAA,SelectAA,VerifyImage,Complete};
 Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}StartupChild child()const{return child_;}bool awaiting()const{return child_!=StartupChild::None;}void resume(){child_=StartupChild::None;}uint8_t marker()const{return marker_;}bool romCopy()const{return marker_==0x55||marker_==0xaa;}
 unsigned nextClocks(const FlashCredits&c)const{if(awaiting()||complete())return 0;switch(stage_){case Stage::Pins:case Stage::WaitStates:case Stage::PanelReset:case Stage::LcdInitialize:case Stage::InterruptSetup:case Stage::TimerSetup:case Stage::BoundsCheck:case Stage::BootProbe:return c.call;case Stage::RetainDelay:case Stage::RetainInner:return c.pushWord;case Stage::ReleaseInner:case Stage::ReleaseDelay:return c.popWord;case Stage::CountSettling:case Stage::CountDelay:return 6;case Stage::PublishMarker:return 9+c.write;case Stage::ReadMarker:return 9+c.read;case Stage::Select55:case Stage::SelectAA:case Stage::VerifyImage:return 8;default:return 3;}}
 template<class R,class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::Pins:child_=StartupChild::Pins;break;case Stage::WaitStates:child_=StartupChild::WaitStates;break;case Stage::PanelReset:child_=StartupChild::PanelReset;break;case Stage::CountSettling:settling_=10;break;case Stage::CountDelay:delay_=2663;break;case Stage::TickDelay:--delay_;break;case Stage::RepeatDelay:if(delay_)next=Stage::TickDelay;break;case Stage::TickSettling:--settling_;break;case Stage::RepeatSettling:if(settling_)next=Stage::RetainInner;break;case Stage::LcdInitialize:child_=StartupChild::LcdInitialize;break;case Stage::InterruptSetup:child_=StartupChild::InterruptSetup;break;case Stage::TimerSetup:child_=StartupChild::TimerSetup;break;case Stage::BoundsCheck:child_=StartupChild::BoundsCheck;break;case Stage::PublishMarker:write(0);break;case Stage::BootProbe:child_=StartupChild::BootProbe;break;case Stage::ReadMarker:marker_=uint8_t(read());break;case Stage::Select55:if(marker_==0x55)next=Stage::Complete;break;case Stage::SelectAA:if(marker_==0xaa)next=Stage::Complete;break;case Stage::VerifyImage:next=Stage::Complete;break;default:break;}stage_=next;return cost;}
private:Stage stage_=Stage::Pins;StartupChild child_=StartupChild::None;uint8_t marker_=0,settling_=0;uint16_t delay_=0;};
class StartupRuntimeTask final {
public:enum class Stage{LcdInitialize,KeyboardInitialize,SerialSetup,SerialEnable,EncoderInitialize,PanelQueues,InterruptSetup,TimerSetup,Unmask,AdcStart,DspBootstrap,DspGlobals,DelayTables,StartupBanner,LcdAgain,LcdCharacters,Return,Complete};
 Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}StartupChild child()const{return child_;}bool awaiting()const{return child_!=StartupChild::None;}void resume(){child_=StartupChild::None;}
 unsigned nextClocks(const FlashCredits&c)const{return awaiting()||complete()?0:stage_==Stage::Unmask?3:stage_==Stage::Return?c.ret:c.call;}
 unsigned advanceBefore(unsigned budget,const FlashCredits&c){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;switch(stage_){case Stage::LcdInitialize:case Stage::LcdAgain:child_=StartupChild::LcdInitialize;break;case Stage::KeyboardInitialize:child_=StartupChild::KeyboardInitialize;break;case Stage::SerialSetup:child_=StartupChild::SerialSetup;break;case Stage::SerialEnable:child_=StartupChild::SerialEnable;break;case Stage::EncoderInitialize:child_=StartupChild::EncoderInitialize;break;case Stage::PanelQueues:child_=StartupChild::PanelQueues;break;case Stage::InterruptSetup:child_=StartupChild::InterruptSetup;break;case Stage::TimerSetup:child_=StartupChild::TimerSetup;break;case Stage::AdcStart:child_=StartupChild::AdcStart;break;case Stage::DspBootstrap:child_=StartupChild::DspBootstrap;break;case Stage::DspGlobals:child_=StartupChild::DspGlobals;break;case Stage::DelayTables:child_=StartupChild::DelayTables;break;case Stage::StartupBanner:child_=StartupChild::StartupBanner;break;case Stage::LcdCharacters:child_=StartupChild::LcdCharacters;break;default:break;}stage_=Stage(unsigned(stage_)+1);return cost;}
private:Stage stage_=Stage::LcdInitialize;StartupChild child_=StartupChild::None;};
class StartupMainTask final {
public:enum class Stage{Metadata,Scheduler1,Scheduler2,Scheduler3,Scheduler4,Scheduler5,ClearUi,ArpInitialize,MidiInitialize,ClockInitialize,BindAdc,ReadAdc,ScaleAdc,RetainAdc,ApplyAdc,BindBackup,BackupGlobals,LoadGlobals,BindSelection,ReadBank,ReadProgram,PublishBank,PublishProgram,LoadProgram,UpdateDisplay,ReadTick,PublishTick,Complete};
 enum class Read{Bank,Program};enum class Write{Bank,Program,Tick};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}StartupChild child()const{return child_;}bool awaiting()const{return child_!=StartupChild::None;}void resume(uint16_t value=0){if(child_==StartupChild::ReadAdc)adc_=uint8_t(value);if(child_==StartupChild::ReadTick)tick_=value;child_=StartupChild::None;}
 unsigned nextClocks(const FlashCredits&c)const{if(awaiting()||complete())return 0;switch(stage_){case Stage::BindBackup:case Stage::BindSelection:return 9;case Stage::ReadBank:case Stage::ReadProgram:return 12+c.read;case Stage::PublishBank:case Stage::PublishProgram:case Stage::PublishTick:return 9+c.write;case Stage::BindAdc:case Stage::ScaleAdc:case Stage::RetainAdc:return 3;default:return c.call;}}
 template<class R,class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;switch(stage_){case Stage::Metadata:child_=StartupChild::Metadata;break;case Stage::Scheduler1:child_=StartupChild::Scheduler1;break;case Stage::Scheduler2:child_=StartupChild::Scheduler2;break;case Stage::Scheduler3:child_=StartupChild::Scheduler3;break;case Stage::Scheduler4:child_=StartupChild::Scheduler4;break;case Stage::Scheduler5:child_=StartupChild::Scheduler5;break;case Stage::ClearUi:child_=StartupChild::ClearUi;break;case Stage::ArpInitialize:child_=StartupChild::ArpInitialize;break;case Stage::MidiInitialize:child_=StartupChild::MidiInitialize;break;case Stage::ClockInitialize:child_=StartupChild::ClockInitialize;break;case Stage::ReadAdc:child_=StartupChild::ReadAdc;break;case Stage::ScaleAdc:adc_>>=1;break;case Stage::ApplyAdc:child_=StartupChild::ApplyAdc;break;case Stage::BackupGlobals:child_=StartupChild::BackupGlobals;break;case Stage::LoadGlobals:child_=StartupChild::LoadGlobals;break;case Stage::ReadBank:bank_=uint8_t(read(Read::Bank));break;case Stage::ReadProgram:program_=uint8_t(read(Read::Program));break;case Stage::PublishBank:write(Write::Bank,bank_);break;case Stage::PublishProgram:write(Write::Program,program_);break;case Stage::LoadProgram:child_=StartupChild::LoadProgram;break;case Stage::UpdateDisplay:child_=StartupChild::UpdateDisplay;break;case Stage::ReadTick:child_=StartupChild::ReadTick;break;case Stage::PublishTick:write(Write::Tick,tick_);break;default:break;}stage_=Stage(unsigned(stage_)+1);return cost;}
private:Stage stage_=Stage::Metadata;StartupChild child_=StartupChild::None;uint8_t adc_=0,bank_=0,program_=0;uint16_t tick_=0;};
}
